//! Replays the golden corpus generated by
//! `electricity/scripts/generate_validate_yaml_corpus.py` -- real
//! output from Circuitry's own `ValidateYamlPlugin.execute`
//! (`plugins/validate_yaml.py`) -- against this crate's
//! `validate_yaml::ValidateYamlPlugin`.
//!
//! The corpus is checked in (`tests/golden/validate_yaml_corpus.json`);
//! CI separately regenerates it with Python 3.11 and fails the build
//! if it differs (`.github/workflows/electricity-generated.yml`), so
//! this test only needs to trust the committed file.
//!
//! An `errors` entry tagged `exact` is Circuitry's own text, compared
//! word for word; one tagged `third_party` (a PyYAML scan error, a
//! JSON-Schema violation) is compared by its fixed prefix only, with a
//! non-empty rest (DESIGN.md §1, §12) -- never the exact wording.

use chrono::{FixedOffset, NaiveDate, NaiveDateTime};
use electricity_tools::{ToolCall, ToolPlugin, validate_yaml::ValidateYamlPlugin};
use electricity_value::{CancellationToken, Dict, Value};
use serde::Deserialize;

#[derive(Deserialize, Debug)]
#[serde(tag = "t")]
enum TaggedValue {
    #[serde(rename = "none")]
    None,
    #[serde(rename = "bool")]
    Bool { v: bool },
    #[serde(rename = "int")]
    Int { v: String },
    #[serde(rename = "float")]
    Float { bits: String },
    #[serde(rename = "str")]
    Str { v: String },
    #[serde(rename = "bytes")]
    Bytes { hex: String },
    #[serde(rename = "date")]
    Date { v: String },
    #[serde(rename = "datetime")]
    DateTime {
        v: String,
        offset_seconds: Option<i64>,
    },
    #[serde(rename = "list")]
    List { v: Vec<TaggedValue> },
    #[serde(rename = "dict")]
    Dict { v: Vec<(TaggedValue, TaggedValue)> },
}

fn naive_date(v: &str) -> NaiveDate {
    NaiveDate::parse_from_str(v, "%Y-%m-%d").expect("valid ISO date")
}

fn naive_datetime(v: &str) -> NaiveDateTime {
    NaiveDateTime::parse_from_str(v, "%Y-%m-%dT%H:%M:%S%.f").expect("valid ISO datetime")
}

impl From<TaggedValue> for Value {
    fn from(tagged: TaggedValue) -> Self {
        match tagged {
            TaggedValue::None => Value::None,
            TaggedValue::Bool { v } => Value::Bool(v),
            TaggedValue::Int { v } => Value::Int(
                electricity_value::IntValue::parse_decimal(&v).expect("valid decimal integer"),
            ),
            TaggedValue::Float { bits } => {
                let bits = u64::from_str_radix(&bits, 16).expect("valid hex bit pattern");
                Value::Float(f64::from_bits(bits))
            }
            TaggedValue::Str { v } => Value::Str(v),
            TaggedValue::Bytes { hex } => {
                let mut bytes = Vec::with_capacity(hex.len() / 2);
                let mut chars = hex.chars();
                while let (Some(hi), Some(lo)) = (chars.next(), chars.next()) {
                    let byte =
                        u8::from_str_radix(&format!("{hi}{lo}"), 16).expect("valid hex byte");
                    bytes.push(byte);
                }
                Value::Bytes(bytes)
            }
            TaggedValue::Date { v } => Value::Date(naive_date(&v)),
            TaggedValue::DateTime { v, offset_seconds } => Value::DateTime(
                naive_datetime(&v),
                offset_seconds.map(|s| FixedOffset::east_opt(s as i32).expect("valid UTC offset")),
            ),
            TaggedValue::List { v } => Value::List(v.into_iter().map(Value::from).collect()),
            TaggedValue::Dict { v } => {
                let mut dict = Dict::new();
                for (k, val) in v {
                    dict.insert(Value::from(k), Value::from(val));
                }
                Value::Dict(dict)
            }
        }
    }
}

#[derive(Deserialize)]
struct ErrorTag {
    kind: String,
    text: Option<String>,
    prefix: Option<String>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    params: std::collections::BTreeMap<String, TaggedValue>,
    raised: bool,
    error: Option<String>,
    /// Only present when `raised`: `type(exc).__name__` (review finding 3
    /// on PR #524 -- previously only the message text was recorded, so a
    /// `ValueError` and the `OverflowError` finding 4 adds couldn't be
    /// told apart here).
    #[serde(default)]
    py_class: Option<String>,
    tool_ok: Option<bool>,
    value_ok: Option<bool>,
    yaml_echo: Option<String>,
    stderr: Option<String>,
    errors: Option<Vec<ErrorTag>>,
    /// Several schema errors compare as a multiset of locations (DESIGN.md's
    /// own Hazards section: Python sorts by `str(err)`, electricity by
    /// `(location, message)`) -- review finding 3 on PR #524.
    #[serde(default)]
    errors_unordered: bool,
}

#[derive(Deserialize)]
struct Corpus {
    cases: Vec<Case>,
}

fn params_value(case: &Case) -> Value {
    let mut dict = Dict::new();
    for (key, value) in &case.params {
        // `TaggedValue` isn't `Clone`; re-deserializing per case is not
        // an option either (ownership, not performance, is the issue
        // here) -- so this test owns the map directly rather than
        // through a borrowed iteration, consuming it once.
        dict.insert(Value::Str(key.clone()), clone_tagged(value));
    }
    Value::Dict(dict)
}

/// A hand-rolled clone for [`TaggedValue`] -- deriving `Clone` would
/// also require it on `serde`'s own generated code paths this test
/// doesn't otherwise need; a corpus case's own params map is small
/// (at most four keys), so a recursive match costs nothing measurable.
fn clone_tagged(value: &TaggedValue) -> Value {
    match value {
        TaggedValue::None => Value::None,
        TaggedValue::Bool { v } => Value::Bool(*v),
        TaggedValue::Int { v } => Value::Int(
            electricity_value::IntValue::parse_decimal(v).expect("valid decimal integer"),
        ),
        TaggedValue::Float { bits } => {
            let bits = u64::from_str_radix(bits, 16).expect("valid hex bit pattern");
            Value::Float(f64::from_bits(bits))
        }
        TaggedValue::Str { v } => Value::Str(v.clone()),
        TaggedValue::Bytes { hex } => {
            let mut bytes = Vec::with_capacity(hex.len() / 2);
            let mut chars = hex.chars();
            while let (Some(hi), Some(lo)) = (chars.next(), chars.next()) {
                let byte = u8::from_str_radix(&format!("{hi}{lo}"), 16).expect("valid hex byte");
                bytes.push(byte);
            }
            Value::Bytes(bytes)
        }
        TaggedValue::Date { v } => Value::Date(naive_date(v)),
        TaggedValue::DateTime { v, offset_seconds } => Value::DateTime(
            naive_datetime(v),
            offset_seconds.map(|s| FixedOffset::east_opt(s as i32).expect("valid UTC offset")),
        ),
        TaggedValue::List { v } => Value::List(v.iter().map(clone_tagged).collect()),
        TaggedValue::Dict { v } => {
            let mut dict = Dict::new();
            for (k, val) in v {
                dict.insert(clone_tagged(k), clone_tagged(val));
            }
            Value::Dict(dict)
        }
    }
}

#[tokio::test]
async fn golden_corpus_validate_yaml() {
    let text = include_str!("golden/validate_yaml_corpus.json");
    let corpus: Corpus =
        serde_json::from_str(text).expect("golden/validate_yaml_corpus.json is valid JSON");
    assert!(!corpus.cases.is_empty());

    let tool = ValidateYamlPlugin;
    let token = CancellationToken::new();
    let none_config = Value::None;
    let call = ToolCall {
        timeout_seconds: 30,
        config: &none_config,
        token: &token,
        armed: false,
    };

    let mut failures = Vec::new();
    for case in &corpus.cases {
        let params = params_value(case);
        let result = tool.execute(params, &call).await;
        match result {
            Err(err) => {
                if !case.raised {
                    failures.push(format!(
                        "{}: expected success, raised {:?}",
                        case.name, err.message
                    ));
                    continue;
                }
                let expected = case.error.as_deref().unwrap_or_default();
                if err.message != expected {
                    failures.push(format!(
                        "{}: expected error {expected:?}, got {:?}",
                        case.name, err.message
                    ));
                }
                if let Some(expected_class) = case.py_class.as_deref() {
                    if err.py_class.name() != expected_class {
                        failures.push(format!(
                            "{}: expected py_class {expected_class:?}, got {:?}",
                            case.name,
                            err.py_class.name()
                        ));
                    }
                }
            }
            Ok(got) => {
                if case.raised {
                    failures.push(format!(
                        "{}: expected a raise, got value {:?}",
                        case.name, got.value
                    ));
                    continue;
                }
                if got.ok != case.tool_ok.unwrap_or(true) {
                    failures.push(format!(
                        "{}: ToolResult.ok mismatch: {:?}",
                        case.name, got.ok
                    ));
                }
                let dict = got.value.as_dict().expect("value is a dict");
                let value_ok = dict
                    .get(&Value::Str("ok".to_string()))
                    .and_then(Value::as_bool)
                    .expect("value['ok'] is a bool");
                if Some(value_ok) != case.value_ok {
                    failures.push(format!("{}: value['ok'] mismatch: {value_ok:?}", case.name));
                }
                let yaml_echo = dict
                    .get(&Value::Str("yaml".to_string()))
                    .and_then(Value::as_str)
                    .expect("value['yaml'] is a str");
                if Some(yaml_echo.to_string()) != case.yaml_echo {
                    failures.push(format!("{}: yaml echo mismatch: {yaml_echo:?}", case.name));
                }
                assert_eq!(
                    got.stdout, None,
                    "{}: stdout must always be None",
                    case.name
                );
                assert_eq!(
                    got.exit_code, None,
                    "{}: exit_code must always be None",
                    case.name
                );
                assert_eq!(got.raw, got.value, "{}: raw must equal value", case.name);

                let got_errors: Vec<String> = dict
                    .get(&Value::Str("errors".to_string()))
                    .and_then(Value::as_list)
                    .expect("value['errors'] is a list")
                    .iter()
                    .map(|v| v.as_str().expect("each error is a str").to_string())
                    .collect();
                let expected_tags = case.errors.as_deref().unwrap_or_default();
                if got_errors.len() != expected_tags.len() {
                    failures.push(format!(
                        "{}: error count mismatch: got {got_errors:?}, expected {} tags",
                        case.name,
                        expected_tags.len()
                    ));
                    continue;
                }
                let check_one = |got_text: &str, tag: &ErrorTag, failures: &mut Vec<String>| {
                    match tag.kind.as_str() {
                        "exact" => {
                            let expected = tag.text.as_deref().unwrap_or_default();
                            if got_text != expected {
                                failures.push(format!(
                                    "{}: exact error mismatch: got {got_text:?}, expected {expected:?}",
                                    case.name
                                ));
                            }
                        }
                        "third_party" => {
                            let prefix = tag.prefix.as_deref().unwrap_or_default();
                            match got_text.strip_prefix(prefix) {
                                Some(rest) if !rest.is_empty() => {}
                                _ => failures.push(format!(
                                    "{}: third-party error {got_text:?} does not start with \
                                     {prefix:?} with a non-empty rest",
                                    case.name
                                )),
                            }
                        }
                        other => failures
                            .push(format!("{}: unknown error tag kind {other:?}", case.name)),
                    }
                };
                if case.errors_unordered {
                    // Several schema errors compare as a multiset of
                    // locations (DESIGN.md's own Hazards section): sort
                    // both sides by their own comparison key before
                    // pairing them up, rather than by position.
                    let mut got_sorted = got_errors.clone();
                    got_sorted.sort();
                    let mut tags_sorted: Vec<&ErrorTag> = expected_tags.iter().collect();
                    tags_sorted.sort_by_key(|tag| match tag.kind.as_str() {
                        "exact" => tag.text.clone().unwrap_or_default(),
                        _ => tag.prefix.clone().unwrap_or_default(),
                    });
                    for (got_text, tag) in got_sorted.iter().zip(tags_sorted) {
                        check_one(got_text, tag, &mut failures);
                    }
                } else {
                    for (got_text, tag) in got_errors.iter().zip(expected_tags) {
                        check_one(got_text, tag, &mut failures);
                    }
                }

                // `stderr` is the errors joined with `"\n"` -- compared
                // exactly only when every error in this case is `exact`
                // text; a case carrying a `third_party` error already
                // has its own text checked above, so here only
                // presence/absence (matching whether there were any
                // errors at all) is checked.
                let all_exact = expected_tags.iter().all(|tag| tag.kind == "exact");
                if all_exact {
                    let expected_stderr = if got_errors.is_empty() {
                        None
                    } else {
                        Some(got_errors.join("\n"))
                    };
                    if got.stderr != expected_stderr {
                        failures.push(format!("{}: stderr mismatch: {:?}", case.name, got.stderr));
                    }
                    if got.stderr != case.stderr {
                        failures.push(format!(
                            "{}: stderr does not match the corpus's own recorded stderr: {:?}",
                            case.name, got.stderr
                        ));
                    }
                } else if got.stderr.is_none() != got_errors.is_empty() {
                    failures.push(format!(
                        "{}: stderr presence does not match whether there were any errors: {:?}",
                        case.name, got.stderr
                    ));
                }
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
